export type HotFileWriteOwner = string;

export type HotFileWriteToken = string;

export type HotFileWriteOwnerStatus =
  | "claimed"
  | "reentrant"
  | "conflict"
  | "released"
  | "not-owner";

export interface HotFileWriteOwnerClaim {
  readonly status: "claimed" | "reentrant";
  readonly path: string;
  readonly owner: HotFileWriteOwner;
  readonly token: HotFileWriteToken;
  readonly holder?: HotFileWriteOwner;
}

export interface HotFileWriteOwnerConflict {
  readonly status: "conflict";
  readonly path: string;
  readonly owner: HotFileWriteOwner;
  readonly holder: HotFileWriteOwner;
}

export interface HotFileWriteOwnerRelease {
  readonly status: "released" | "not-owner";
  readonly path: string;
  readonly owner: HotFileWriteOwner;
  readonly token: HotFileWriteToken;
}

export interface FileMutationQueue {
  runExclusive<T>(path: string, task: () => Promise<T> | T): Promise<T>;
}

export interface HotFileWriteOwnerOptions {
  readonly mutationQueue: FileMutationQueue;
  readonly timeoutMs?: number;
}

interface OwnerRecord {
  readonly owner: HotFileWriteOwner;
  readonly token: HotFileWriteToken;
}

const owners = new Map<string, OwnerRecord>();

function assertPath(path: string): void {
  if (!path.trim()) {
    throw new Error("hot-file write owner requires a non-empty path");
  }
}

function assertIdentity(owner: HotFileWriteOwner, token: HotFileWriteToken): void {
  if (!owner.trim() || !token.trim()) {
    throw new Error("hot-file write owner requires a non-empty owner and token");
  }
}

function runWithTimeout<T>(
  operation: () => Promise<T> | T,
  timeoutMs: number | undefined,
): Promise<T> {
  if (timeoutMs === undefined) {
    return Promise.resolve().then(operation);
  }

  return new Promise<T>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (!settled) {
        settled = true;
        reject(new Error(`hot-file write owner operation timed out after ${timeoutMs}ms`));
      }
    }, timeoutMs);

    Promise.resolve()
      .then(operation)
      .then(
        (value) => {
          if (!settled) {
            settled = true;
            clearTimeout(timer);
            resolve(value);
          }
        },
        (error: unknown) => {
          if (!settled) {
            settled = true;
            clearTimeout(timer);
            reject(error);
          }
        },
      );
  });
}

/**
 * Claims a path through the existing per-file mutation queue. The queue is the
 * only scheduler used here; ownership checks happen inside its exclusive task.
 */
export async function claimHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
  options: HotFileWriteOwnerOptions,
): Promise<HotFileWriteOwnerClaim | HotFileWriteOwnerConflict> {
  assertPath(path);
  assertIdentity(owner, token);

  return runWithTimeout(
    () =>
      options.mutationQueue.runExclusive(path, async () => {
        const current = owners.get(path);
        if (!current) {
          owners.set(path, { owner, token });
          return { status: "claimed", path, owner, token } as const;
        }
        if (current.owner === owner && current.token === token) {
          return { status: "reentrant", path, owner, token } as const;
        }
        return {
          status: "conflict",
          path,
          owner,
          holder: current.owner,
        } as const;
      }),
    options.timeoutMs,
  );
}

/** Releases a claim only when both owner and token match. */
export async function releaseHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
  options: HotFileWriteOwnerOptions,
): Promise<HotFileWriteOwnerRelease> {
  assertPath(path);
  assertIdentity(owner, token);

  return runWithTimeout(
    () =>
      options.mutationQueue.runExclusive(path, async () => {
        const current = owners.get(path);
        if (
          !current ||
          current.owner !== owner ||
          current.token !== token
        ) {
          return { status: "not-owner", path, owner, token } as const;
        }
        owners.delete(path);
        return { status: "released", path, owner, token } as const;
      }),
    options.timeoutMs,
  );
}

/**
 * Executes a write while its claim is held. The write is queued by the same
 * mutation queue used for claims, and a failed write always releases the claim.
 */
export async function withHotFileWriteOwner<T>(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
  write: () => Promise<T> | T,
  options: HotFileWriteOwnerOptions,
): Promise<T> {
  assertPath(path);
  assertIdentity(owner, token);

  const claim = await claimHotFileWriteOwner(path, owner, token, options);
  if (claim.status === "conflict") {
    throw new Error(
      `hot-file write conflict for ${path}: owner ${owner} is held by ${claim.holder}`,
    );
  }

  try {
    return await runWithTimeout(write, options.timeoutMs);
  } catch (error) {
    await releaseHotFileWriteOwner(path, owner, token, options);
    throw error;
  } finally {
    // A successful write remains claimed until the caller explicitly releases
    // it; a failed write is released above so ownership cannot leak.
    if ((await currentClaimMatches(path, owner, token)) === false) {
      await releaseHotFileWriteOwner(path, owner, token, options);
    }
  }
}

async function currentClaimMatches(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
): Promise<boolean> {
  const current = owners.get(path);
  return current?.owner === owner && current.token === token;
}

export const claimFileWriteOwner = claimHotFileWriteOwner;
export const releaseFileWriteOwner = releaseHotFileWriteOwner;
export const withFileWriteOwner = withHotFileWriteOwner;

